+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Server Log</title>
+  <style>
+    :root {
+      --bg: #eaf6ef;
+      --ink: #10291d;
+      --muted: #5f7569;
+      --card: rgba(255, 255, 255, 0.92);
+      --line: #c7dfd0;
+      --line-strong: #8fbda1;
+      --accent: #1d6b3a;
+      --accent-dark: #15552d;
+      --accent-soft: #dff3e7;
+      --shadow: rgba(18, 57, 35, 0.16);
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      padding: 40px 16px;
+      display: grid;
+      place-items: center;
+      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      background:
+        radial-gradient(circle at top left, rgba(29, 107, 58, 0.18), transparent 34%),
+        linear-gradient(135deg, #f5fbf7 0%, var(--bg) 48%, #dcefe4 100%);
+      color: var(--ink);
+    }
+
+    main {
+      width: min(1080px, 100%);
+      overflow: hidden;
+      background: var(--card);
+      border: 1px solid rgba(199, 223, 208, 0.9);
+      border-radius: 24px;
+      box-shadow: 0 24px 70px var(--shadow);
+      backdrop-filter: blur(14px);
+    }
+
+    .hero {
+      padding: 30px;
+      display: grid;
+      gap: 14px;
+      background: linear-gradient(135deg, rgba(29, 107, 58, 0.12), rgba(223, 243, 231, 0.35));
+      border-bottom: 1px solid var(--line);
+    }
+
+    .eyebrow {
+      width: fit-content;
+      padding: 6px 10px;
+      border: 1px solid var(--line-strong);
+      border-radius: 999px;
+      background: rgba(255, 255, 255, 0.62);
+      color: var(--accent-dark);
+      font-size: 12px;
+      font-weight: 800;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(32px, 5vw, 48px);
+      line-height: 1;
+      letter-spacing: -0.04em;
+    }
+
+    p {
+      margin: 0;
+      max-width: 620px;
+      color: var(--muted);
+      line-height: 1.7;
+    }
+
+    .content {
+      padding: 30px;
+      display: grid;
+      gap: 22px;
+    }
+
+    .section {
+      padding: 22px;
+      border: 1px solid var(--line);
+      border-radius: 18px;
+      background: rgba(255, 255, 255, 0.78);
+    }
+
+    .section h2 {
+      margin: 0 0 4px;
+      font-size: 18px;
+      letter-spacing: -0.02em;
+    }
+
+    .section p {
+      margin-bottom: 18px;
+      font-size: 14px;
+    }
+
+    .metadata {
+      display: grid;
+      gap: 16px;
+      grid-template-columns: repeat(4, minmax(0, 1fr));
+    }
+
+    .meta-card {
+      display: grid;
+      gap: 8px;
+      padding: 16px;
+      border: 1px solid var(--line);
+      border-radius: 14px;
+      background: #fbfffc;
+    }
+
+    .meta-label {
+      color: var(--muted);
+      font-size: 12px;
+      font-weight: 800;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    .meta-value {
+      color: var(--ink);
+      font-size: 15px;
+      font-weight: 800;
+      line-height: 1.4;
+      overflow-wrap: anywhere;
+    }
+
+    .status {
+      margin-top: 16px;
+      padding: 12px 14px;
+      border: 1px solid var(--line-strong);
+      border-radius: 14px;
+      background: var(--accent-soft);
+      color: var(--accent-dark);
+      font-size: 14px;
+      font-weight: 800;
+      line-height: 1.45;
+    }
+
+    pre {
+      margin: 0;
+      max-height: 68vh;
+      overflow: auto;
+      padding: 18px;
+      border: 1px solid var(--line-strong);
+      border-radius: 14px;
+      background: #fbfffc;
+      color: var(--ink);
+      font: 13px/1.6 "SFMono-Regular", Consolas, "Liberation Mono", monospace;
+      white-space: pre-wrap;
+      word-break: break-word;
+    }
+
+    .actions {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      padding-top: 2px;
+    }
+
+    .back-link {
+      color: var(--accent-dark);
+      font-size: 14px;
+      font-weight: 800;
+      text-decoration: none;
+    }
+
+    .back-link:hover {
+      text-decoration: underline;
+    }
+
+    @media (max-width: 820px) {
+      .metadata {
+        grid-template-columns: repeat(2, minmax(0, 1fr));
+      }
+    }
+
+    @media (max-width: 680px) {
+      body {
+        padding: 18px 12px;
+      }
+
+      .hero,
+      .content {
+        padding: 22px;
+      }
+
+      .metadata,
+      .actions {
+        grid-template-columns: 1fr;
+      }
+
+      .actions {
+        display: grid;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <div class="hero">
+      <div class="eyebrow">WebServer Logs</div>
+      <h1>Server Log</h1>
+      <p>Review the selected server log file with preserved line spacing and rotation metadata.</p>
+    </div>
+
+    <div class="content">
+      <section class="section" aria-labelledby="log-metadata-heading">
+        <h2 id="log-metadata-heading">Log Metadata</h2>
+        <p>Status and file details for the selected log snapshot.</p>
+        <div class="metadata">
+          <div class="meta-card">
+            <span class="meta-label">Date</span>
+            <span class="meta-value">{{log.date}}</span>
+          </div>
+
+          <div class="meta-card">
+            <span class="meta-label">File Index</span>
+            <span class="meta-value">{{log.file_index}}</span>
+          </div>
+
+          <div class="meta-card">
+            <span class="meta-label">File Name</span>
+            <span class="meta-value">{{log.file_name}}</span>
+          </div>
+
+          <div class="meta-card">
+            <span class="meta-label">Line Count</span>
+            <span class="meta-value">{{log.line_count}}</span>
+          </div>
+        </div>
+        <div class="status">{{log.status_message}}</div>
+      </section>
+
+      <section class="section" aria-labelledby="log-contents-heading">
+        <h2 id="log-contents-heading">Log Contents</h2>
+        <p>Escaped log output is rendered below with whitespace preserved.</p>
+        <pre>{{log.contents}}</pre>
+      </section>
+
+      <div class="actions">
+        <a class="back-link" href="/index.html">Back to home</a>
+      </div>
+    </div>
+  </main>
+</body>
+</html>
*** End Patch

